-- Finance (PRIVATE_FINANCIAL): owner-only, never employer/org accessible. Apply to USER project only.
create table if not exists public.finance_imports (id uuid primary key default gen_random_uuid(), user_id uuid not null, client_ref text, filename text, file_type text, row_count int default 0, imported_count int default 0, duplicate_count int default 0, rejected_count int default 0, date_min date, date_max date, currency text default 'GBP', status text default 'completed' check (status in ('uploaded','parsed','awaiting_confirmation','importing','completed','failed')), privacy_classification text default 'PRIVATE_FINANCIAL', created_at timestamptz default now(), completed_at timestamptz);
create table if not exists public.finance_transactions (id uuid primary key default gen_random_uuid(), user_id uuid not null, import_id uuid references public.finance_imports(id) on delete set null, client_ref text, transaction_date date not null, description_raw text not null, merchant_normalized text, amount_minor bigint not null, currency text default 'GBP', direction text check (direction in ('in','out')), category text, balance_minor bigint, is_recurring boolean default false, recurring_group_id text, is_transfer boolean default false, confidence numeric default 0.5, source_row_hash text not null, privacy_classification text default 'PRIVATE_FINANCIAL', created_at timestamptz default now(), updated_at timestamptz default now(), unique(user_id, source_row_hash));
create table if not exists public.finance_merchant_rules (id uuid primary key default gen_random_uuid(), user_id uuid not null, merchant_pattern text, merchant_normalized text, category text, source text default 'user', confidence numeric default 1, created_at timestamptz default now(), unique(user_id, merchant_normalized));
create table if not exists public.finance_recurring_items (id uuid primary key default gen_random_uuid(), user_id uuid not null, client_ref text, merchant text, category text, average_amount_minor bigint, currency text default 'GBP', frequency text, next_expected_date date, confidence numeric, active boolean default true, first_seen date, last_seen date, created_at timestamptz default now(), unique(user_id, client_ref));
create table if not exists public.finance_analysis_snapshots (id uuid primary key default gen_random_uuid(), user_id uuid not null, period_start date, period_end date, currency text, metrics_json jsonb default '{}', analysis_json jsonb default '{}', model text, created_at timestamptz default now());
-- Original files are NOT retained by default (deleted after processing). If retention is ever enabled: private bucket, owner-only, signed URLs only.
do $$ declare t text; begin for t in select unnest(array['finance_imports','finance_transactions','finance_merchant_rules','finance_recurring_items','finance_analysis_snapshots']) loop
  execute format('alter table public.%I enable row level security', t);
  execute format('drop policy if exists "owner all" on public.%I', t);
  execute format('create policy "owner all" on public.%I for all using (auth.uid() = user_id) with check (auth.uid() = user_id)', t);
end loop; end $$;
create unique index if not exists finance_imports_user_client_uidx on public.finance_imports(user_id, client_ref) where client_ref is not null;
create index if not exists finance_tx_user_date_idx on public.finance_transactions(user_id, transaction_date desc);
